//! L08-G: GPU layer isolation + blend / track-matte / mask passes on the real
//! headless Metal compositor, compared with literals from the baseline oracle.
//!
//! `fixtures/scene-effect-gpu-blend/oracle.txt` (see the support module) was
//! generated by `tools/gen_scene_effect_gpu_blend_oracle.js` from the baseline
//! `blend.wgsl`, `matte.wgsl` and `composite_scene` at fbe4b8a3: 40 scenes on
//! an 8x8 canvas, every texture write quantised to RGBA8. The GPU result is
//! the actual `Compositor::compose_layered_stack` readback; tolerance per case
//! is 1 channel step for opaque scenes (one shader rounding) and 3 for
//! translucent scenes (vello's straight-RGB packing plus up to three
//! quantising passes). Metal readback is never an installed result.
use super::support::{check_case, oracle, parse, run_group, ORACLE, SIDE};

#[test]
fn oracle_is_well_formed_and_every_case_has_a_full_expected_image() {
    let cases = parse(ORACLE);
    assert_eq!(cases.len(), 40);
    for case in &cases {
        assert_eq!(case.expect.len(), SIDE * SIDE * 4, "{}", case.name);
        assert!(!case.layers.is_empty(), "{}", case.name);
        assert!(matches!(case.tol, 1 | 3), "{}", case.name);
    }
    let names: std::collections::HashSet<&str> = cases.iter().map(|c| c.name.as_str()).collect();
    assert_eq!(names.len(), cases.len(), "case names are unique");
    let count = |prefix: &str| cases.iter().filter(|c| c.name.starts_with(prefix)).count();
    assert_eq!(count("blend-"), 20);
    assert_eq!(count("matte-"), 7);
    assert_eq!(count("mask-"), 9);
    assert_eq!(
        count("canvas-background") + count("base-colour") + count("effect-layer"),
        4
    );
}

#[test]
fn oracle_header_pins_the_baseline_sources() {
    for pin in [
        "# baseline commit fbe4b8a33e6d5a229f014154df2ba21988a9fabc",
        "# sha256 blend.wgsl (whole) = b928fda02ee59558fffc226e9edfe3fbe24949b2d2e3d097b428987b17691ded",
        "# sha256 matte.wgsl (whole) = aa7aceaed9ff236b86a5f835762013cd19bc4ed82e12d583ea7ac074916aecfa",
        "# sha256 engine.rs mix_mode_index = 8d4973963245be876bed1e3e7502e109322bbfd3dcefeaca6cf52e0497da701e",
        "# sha256 engine.rs matte_mode_of = 6a7269afe869de450930b4b3566b51d07e0106fd5f65f3904d6315700261d4c6",
        "# sha256 geometry-wasm/src/engine.rs (whole) = 1a5e3729dc57922e9c91aa8d4782572f920bc291de331332f4b03b2a27f1cc64",
    ] {
        assert!(ORACLE.lines().any(|line| line == pin), "{pin}");
    }
}

